const zmq = require('zeromq');
const crypto = require('crypto');

const sock = zmq.socket('dealer');
sock.identity = crypto.randomBytes(5).toString('hex'); // Generate a unique identity

sock.connect('tcp://127.0.0.1:57503');
console.log(`Producer (dealer) connected to port 57503 with identity ${sock.identity}`);

const testMsg = {
  header: {
    msg_id: crypto.randomUUID(),
    username: "test",
    session: crypto.randomUUID(),
    msg_type: "kernel_info_request",
    version: "5.0"
  },
  parent_header: {},
  metadata: {},
  content: {},
  buffers: []
};

setInterval(() => {
  console.log('sending work');
  sock.send(JSON.stringify(testMsg));
}, 500);

sock.on('message', function(msg) {
  console.log('Received reply: %s', msg.toString());
});
